// Siapkan permintaan ke model AI vision (format OpenAI-compatible: OpenAI, OpenRouter, Groq, dll.)
const kelompok = $('Ambil kelompok.json').first().json;
const daftar = (Array.isArray(kelompok) ? kelompok : kelompok.data || []).map(k => `${k.kode}: ${k.teks}`).join('\n');
const src = $('Gabung masukan').first();
const key = Object.keys(src.binary || {})[0];
if (!key) throw new Error('Tidak ada gambar poster pada masukan.');
const buf = await this.helpers.getBinaryDataBuffer(0, key);
const mime = src.binary[key].mimeType || 'image/jpeg';
const sistem = `Anda membaca poster/pesan PENGUMUMAN pemadaman PLN UP3 Banjarmasin. Jawab HANYA JSON:
{"entri":[{"ulp":"Lambung Mangkurat|Ahmad Yani|<lainnya>","jenis":"terjadwal|darurat|gangguan","tanggal":"YYYY-MM-DD","mulai":"HH:MM","selesai":"HH:MM","blok":[{"teks":"<salin persis teks kotak wilayah>","kode":"<kode kelompok yang teksnya sama/hampir sama, atau BARU>"}],"alasan":"<kalimat sebab, diringkas>"}],"catatan":"<keraguan pembacaan, jika ada>"}
Satu poster bisa memuat beberapa kotak wilayah. Jangan menebak: tulis "?" bila tidak terbaca.
Daftar kelompok yang sudah dikenal:
${daftar}`;
return [{ json: { body: {
  model: $env.PANTAU_AI_MODEL || 'gpt-4o-mini',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sistem },
    { role: 'user', content: [ { type: 'text', text: 'Ekstrak jadwal dari poster ini.' },
      { type: 'image_url', image_url: { url: `data:${mime};base64,${buf.toString('base64')}` } } ] }
  ] }, sumber_url: src.json.sumber_url || '', masuk_via: src.json.masuk_via || '' } }];

// Ubah jawaban AI menjadi baris antrean (status: menunggu verifikasi manusia)
const res = $input.first().json;
const teks = res.choices?.[0]?.message?.content || '{}';
let out; try { out = JSON.parse(teks); } catch (e) { throw new Error('Jawaban AI bukan JSON: ' + teks.slice(0, 300)); }
const meta = $('Siapkan permintaan AI').first().json;
return (out.entri || []).map((e, i) => {
  const kode = (e.blok || []).map(b => b.kode || 'BARU');
  return { json: {
    ulp: e.ulp || '', jenis: e.jenis || 'terjadwal',
    id: `${e.tanggal}-${(e.mulai || '').replace(':', '')}${(out.entri.length > 1) ? '-' + (i + 1) : ''}`,
    tanggal: e.tanggal, mulai: e.mulai, selesai: e.selesai,
    kelompok: kode.join(','),
    teks_wilayah: (e.blok || []).map(b => b.teks).join(' || '),
    alasan: e.alasan || '', poster: '', sumber_url: meta.sumber_url,
    status: 'menunggu', catatan_verifikator: out.catatan || '', masuk_via: meta.masuk_via } };
});

// Kunci unik lintas sumber: ULP + tanggal + jam + kelompok (atau teks wilayah yang dinormalkan).
const norm = s => String(s || '').toLowerCase().replace(/\b(jl|jalan|gg|gang|komp|komplek|kp|dan|sekitarnya|sebagian)\b\.?/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
const kunciDari = r => [String(r.ulp || '').toLowerCase().replace(/\s+/g, ''), r.tanggal, String(r.mulai).slice(0, 5), String(r.selesai).slice(0, 5),
  (r.kelompok && !/BARU|\?/.test(r.kelompok)) ? String(r.kelompok).split(',').map(s => s.trim()).sort().join('+') : norm(r.teks_wilayah).split(' ').sort().slice(0, 12).join('+')].join('|');

const ada = new Set(), sumber = new Set();
for (const r of $('Baca antrean (cek duplikat)').all()) { const j = r.json; if (j.kunci) ada.add(j.kunci); else if (j.tanggal) ada.add(kunciDari(j)); if (j.sumber_url) sumber.add(j.sumber_url); }
const keluar = [];
for (const it of $('Jadikan baris antrean').all()) {
  const r = it.json; r.kunci = kunciDari(r);
  if (ada.has(r.kunci)) continue;            // jadwal sama sudah ada (dari sumber mana pun)
  ada.add(r.kunci); keluar.push({ json: r });
}
return keluar;
